const f = reformer.form();
const co = m=>m.customerType==="company";
const s = "String(m.company.inn)";
const w=[2,4,10,3,5,9,4,6,8];
const sum = w.map((x,i)=>`Number(${s}.charAt(${i}))*${x}`).join("+");
f.field("company.inn").removeRule();
f.field("company.inn").required("Введите ИНН").pattern(/^\d{10}$/,"ИНН — 10 цифр").check(`m => (${sum}) % 11 % 10 === Number(${s}.charAt(9))`,"Неверная контрольная сумма ИНН").when(co).showWhen(co);
f.field("deliveryMethod").options([{value:"pickup",label:"Самовывоз"},{value:"courier",label:"Курьер"},{value:"post",label:"Почта"}]).initial("pickup").required("Выберите способ получения");
const nd = m=>m.deliveryMethod!=="pickup";
f.field("deliveryAddress.city").required("Введите город").when(nd).enableWhen(nd,{resetOnDisable:true});
f.field("deliveryAddress.street").required("Введите улицу").when(nd).enableWhen(nd,{resetOnDisable:true});
f.field("deliveryAddress.house").required("Введите дом").when(nd).enableWhen(nd,{resetOnDisable:true});
const cr = m=>m.deliveryMethod==="courier";
f.field("deliveryDate").type("date").required("Выберите дату доставки").future("Дата доставки — не раньше завтрашнего дня").when(cr).showWhen(cr).resetWhen(m=>m.deliveryMethod!=="courier");
f.field("billingSame").initial(true);
const nb = m=>!m.billingSame;
f.field("billingAddress.city").required("Введите город").when(nb).copyFrom("deliveryAddress.city",m=>m.billingSame).disableWhen(m=>m.billingSame);
f.field("billingAddress.street").required("Введите улицу").when(nb).copyFrom("deliveryAddress.street",m=>m.billingSame).disableWhen(m=>m.billingSame);
f.field("billingAddress.house").required("Введите дом").when(nb).copyFrom("deliveryAddress.house",m=>m.billingSame).disableWhen(m=>m.billingSame);
const it = f.array("items");
it.required("Добавьте хотя бы один товар").max(10,"Не больше 10 товаров");
it.column("title").required("Введите наименование");
it.column("quantity").initial(1).required("Укажите количество").rule("integer()","Количество — целое число").min(1,"Минимум 1").max(99,"Максимум 99");
it.column("price").required("Укажите цену").min(0,"Цена не может быть отрицательной");
it.column("lineTotal").readonly().compute(r=>(r.quantity||0)*(r.price||0));
f.field("subtotal").readonly().compute(m=>m.items.reduce((a,r)=>a+(r.lineTotal||0),0));
f.field("promoCode").transform(v=>String(v).toUpperCase()).asyncCheck(v=>!v||v==="SALE10"||v==="SALE20",{delay:300,message:"Промокод не найден"});
f.field("discount").component("Slider").min(0,"Скидка не может быть отрицательной").max(30,"Скидка не больше 30%").enableWhen(co,{resetOnDisable:true});
f.field("total").readonly().compute(m=>Math.round(m.subtotal*(1-m.discount/100)*100)/100).warning(m=>m.total<=100000,"Крупный заказ: менеджер свяжется для подтверждения");
f.field("paymentMethod").options([{value:"card",label:"Картой онлайн"},{value:"cash",label:"При получении"},{value:"invoice",label:"По счёту"}]).component("RadioGroup").initial("card").required("Выберите способ оплаты").check(m=>m.paymentMethod!=="invoice"||m.customerType==="company","Оплата по счёту — только для юридических лиц").setOnChange("customerType",m=>m.customerType==="person","card");
f.field("receiptEmail").email("Некорректный email для чека").sync("email");
f.field("comment").component("Textarea").maxLength(500,"Не больше 500 символов");
const rc = f.array("recipients");
rc.column("email").required("Введите email получателя").email("Некорректный email получателя");
rc.column("primary").exclusive();
rc.startRows([{primary:true}]);
f.field("agreeTerms").required("Нужно принять условия оферты");
f.field("newsletter").component("Switch");
f.field("sources").component("SelectMulti").options([{value:"search",label:"Поиск"},{value:"friends",label:"Друзья"},{value:"ads",label:"Реклама"},{value:"other",label:"Другое"}]);
f.step("Покупатель").fields("customerType","contact.lastName","contact.firstName","email","phone","birthDate");
f.step("Компания").fields("company.name","company.inn");
f.step("Доставка").fields("deliveryMethod","deliveryAddress.city","deliveryAddress.street","deliveryAddress.house","deliveryDate","billingSame","billingAddress.city","billingAddress.street","billingAddress.house");
f.step("Товары").fields("items","subtotal");
f.step("Оплата").fields("promoCode","discount","total","paymentMethod","receiptEmail","comment");
f.step("Подтверждение").fields("recipients","agreeTerms","newsletter","sources");
console.log(await f.save())

